const $ = s => document.querySelector(s);
const faDate = d => new Intl.DateTimeFormat('fa-IR-u-ca-persian',{year:'numeric',month:'long',day:'numeric'}).format(d);
const faNum = n => new Intl.NumberFormat('fa-IR').format(n);
const iso = d => { const x=new Date(d); return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`; };
let today = iso(new Date());
const uid = () => Math.random().toString(36).slice(2,9)+Date.now().toString(36).slice(-4);

// ثبت پلاگین اختصاصی آلارم برای اندروید
const RoozYarAlarm = window.Capacitor?.Plugins?.RoozYarAlarm || (window.Capacitor?.registerPlugin ? window.Capacitor.registerPlugin('RoozYarAlarm') : null);

const PRESETS = [
 {key:'study',title:'کنکور و مطالعه',icon:'📚',kind:'study',preset:true},
 {key:'internship',title:'گزارش کارآموزی',icon:'📝',kind:'internship',preset:true},
 {key:'health',title:'سلامت و ورزش',icon:'💪',kind:'module',preset:true},
 {key:'finance',title:'مالی و هزینه‌ها',icon:'💳',kind:'module',preset:true},
 {key:'reading',title:'کتاب‌خوانی',icon:'📖',kind:'module',preset:true},
 {key:'projects',title:'پروژه‌های شخصی',icon:'🧩',kind:'module',preset:true},
 {key:'goals',title:'هدف‌های بلندمدت',icon:'🎯',kind:'goals',preset:true}
];
const DEFAULT_DASH = [
 {id:'dash-study',key:'studyMinutes',title:'دقیقه مطالعه امروز',icon:'📚',visible:true},
 {id:'dash-water',key:'water',title:'لیوان آب امروز',icon:'💧',visible:true},
 {id:'dash-internship',key:'internship',title:'فعالیت کاری امروز',icon:'📝',visible:true},
 {id:'dash-goals',key:'goals',title:'هدف‌های فعال',icon:'🎯',visible:true}
];
const defaultState = () => ({
 tasks:[
  {id:uid(),title:'سر کار رفتن',category:'کار',time:'08:00',repeat:'daily',active:true,completedDates:[],alarm:false},
  {id:uid(),title:'باشگاه رفتن',category:'سلامت و ورزش',time:'18:00',repeat:'selected',days:[6,1,3],active:true,completedDates:[],alarm:false},
  {id:uid(),title:'مطالعه کنکور',category:'کنکور و مطالعه',time:'20:00',repeat:'daily',active:true,completedDates:[],alarm:false},
  {id:uid(),title:'مرور کارهای امروز',category:'شخصی',time:'22:00',repeat:'daily',active:true,completedDates:[],alarm:false}
 ],water:{},study:[],internship:[],goals:[{id:uid(),title:'ساخت محصول شخصی',description:'قدم‌به‌قدم تا ساخت یک محصول واقعی',progress:0,deadline:'',done:false}],
 settings:{waterGoal:8,cupMl:250,theme:'midnight',customTheme:{bg:'#10131c',panel:'#1a1f2b',panel2:'#242b3a',line:'#384052',text:'#f3f4fa',muted:'#a6adbd',accent:'#9b8cff',accent2:'#67d7e8'},notifications:false,alarmVolume:70,alarmTone:'classic',pinEnabled:false,pinHash:''},profile:{name:''},
 modules:PRESETS.filter(x=>['study','internship','goals'].includes(x.key)).map((x,i)=>({...x,id:x.key,visible:true,order:i})),moduleEntries:{},
 dashboardCards:DEFAULT_DASH.map(x=>({...x})),
});
function loadState(){try{const old=JSON.parse(localStorage.getItem('roozyar-state-v1'));if(!old)return defaultState();const d=defaultState();const merged={...d,...old,settings:{...d.settings,...(old.settings||{}),waterGoal:Math.min(8,Math.max(1,Number(old.settings?.waterGoal)||8)),theme:old.settings?.theme||'midnight'},profile:{...d.profile,...(old.profile||{})},modules:Array.isArray(old.modules)?old.modules:d.modules,moduleEntries:old.moduleEntries||{},dashboardCards:Array.isArray(old.dashboardCards)?old.dashboardCards:d.dashboardCards};delete merged.firebaseConfig;return merged;}catch{return defaultState()}}
let state=loadState(), page='home', selectedDate=today, calendarMonth=new Date(), activeModuleId=null, toastTimer;
function save(){localStorage.setItem('roozyar-state-v1',JSON.stringify(state));}
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2800)}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function doneToday(t,date=today){return (t.completedDates||[]).includes(date)}
function activeTasks(date=today){const dow=new Date(date+'T12:00:00').getDay();return state.tasks.filter(t=>t.active!==false&&(t.repeat==='daily'||(t.repeat==='selected'&&(t.days||[]).includes(dow))||(t.repeat==='once'&&t.date===date)))}
function taskPercent(date=today){const ts=activeTasks(date);return ts.length?Math.round(ts.filter(t=>doneToday(t,date)).length/ts.length*100):0}
function waterCount(date=today){return Math.min(8,Math.max(0,Number(state.water[date]||0)))}
function setPage(p){page=p;render()}
function header(title,subtitle=''){return `<div class="section-head"><div><h2>${title}</h2>${subtitle?`<div class="muted small">${subtitle}</div>`:''}</div></div>`}
function taskHTML(t,date=today){return `<div class="task-row ${doneToday(t,date)?'done':''}"><input class="check" type="checkbox" data-check="${t.id}" data-date="${date}" ${doneToday(t,date)?'checked':''}><div class="task-content"><div class="task-title">${esc(t.title)}</div><div class="task-meta">${t.time?`◷ ${esc(t.time)} · `:''}${esc(t.category||'شخصی')}${t.alarm?' · 🔔':''}</div></div><button class="icon-btn" data-edit-task="${t.id}" aria-label="ویرایش کار" style="width:32px;height:32px;font-size:14px">⋯</button></div>`}
function dashboardValue(key){if(key==='studyMinutes')return studyMinutesToday();if(key==='water')return `${waterCount()}/${state.settings.waterGoal}`;if(key==='internship')return state.internship.filter(x=>x.date===today).length;if(key==='goals')return state.goals.filter(g=>!g.done).length;if(key.startsWith('module:'))return (state.moduleEntries[key.slice(7)]||[]).filter(x=>x.date===today).length;return '—'}
function streakDays(){let n=0;const d=new Date();if(taskPercent(iso(d))<100)d.setDate(d.getDate()-1);for(let i=0;i<400;i++){const k=iso(d);if(!activeTasks(k).length||taskPercent(k)<100)break;n++;d.setDate(d.getDate()-1)}return n}
function home(){const h=home0(),n=streakDays();return h.replace('<div class="hero','<div class="streak"><b>'+faNum(n)+'</b><span>'+(n?'روز متوالی با همه‌ی کارهای انجام‌شده':'امروز اولین روز زنجیره‌ات را بساز')+'</span></div><div class="hero')}
function home0(){const tasks=activeTasks(),done=tasks.filter(t=>doneToday(t)).length,p=taskPercent(),water=waterCount();const dash=state.dashboardCards.filter(c=>c.visible!==false);const moduleCards=state.modules.filter(m=>m.visible!==false);return `<div class="greeting"><div><div class="eyebrow">یک قدم کوچک، هر روز</div><h1>${state.profile.name?`سلام ${esc(state.profile.name)}`:'سلام، روزت بخیر'} ✨</h1><div class="muted small">امروز را به نفع خودت بساز.</div></div><div class="date-chip">${faDate(new Date())}</div></div>
<div class="hero"><div class="hero-top"><div><h2>داشبورد امروز</h2><div class="muted small">${faNum(done)} کار از ${faNum(tasks.length)} کار انجام شده</div><div style="margin-top:13px"><span class="eyebrow">${p===100?'عالی پیش رفتی!':p>=50?'ادامه بده، خوب پیش می‌ری':'از یک کار کوچک شروع کن'}</span></div></div><div class="progress-ring" style="--progress:${p}%"><b>${faNum(p)}٪</b></div></div><div class="progress-track"><span style="width:${p}%"></span></div></div>
<div class="section-head"><h2>کارت‌های داشبورد</h2><button class="text-btn" data-go="settings">ویرایش کارت‌ها</button></div><div class="grid">${dash.map(c=>`<div class="card stat-card dashboard-card"><div class="stat-icon">${esc(c.icon||'◈')}</div><div class="stat-value">${esc(dashboardValue(c.key))}</div><div class="stat-label">${esc(c.title)}</div><button class="text-btn mini-edit" data-edit-dash="${c.id}">ویرایش</button></div>`).join('')||'<div class="card empty">کارت داشبوردی فعال نیست؛ از تنظیمات اضافه کن.</div>'}</div>
${header('آب خوردن','حداکثر ۸ لیوان در روز؛ هر لیوان را ثبت کن')}<div class="card water-card"><div class="water-head"><div><div class="muted small">مصرف امروز</div><div class="water-count">${faNum(water)} <span class="muted" style="font-size:13px">از ${faNum(state.settings.waterGoal)} لیوان</span></div><div class="muted small">حدود ${faNum(water*state.settings.cupMl)} میلی‌لیتر</div></div><div class="stat-icon water-icon">💧</div></div><div class="water-cups">${Array.from({length:8},(_,i)=>`<button class="cup ${i<water?'filled':''}" data-water="${i+1}" aria-label="ثبت ${i+1} لیوان">${i<water?'✓':'·'}</button>`).join('')}</div><div class="water-actions"><button class="btn primary" data-water-add="1" ${water>=8?'disabled':''}>＋ ثبت یک لیوان</button><button class="btn secondary" data-water-add="-1" ${water<=0?'disabled':''}>− اصلاح</button></div>${water>=8?'<div class="muted small water-limit">حداکثر ۸ لیوان ثبت شده است.</div>':''}</div>
${header('کارهای امروز',faDate(new Date()))}<div class="card">${tasks.length?tasks.slice(0,5).map(t=>taskHTML(t)).join(''):'<div class="empty">برای امروز هنوز کاری تعریف نکردی.</div>'}<button class="add-btn" data-add-task>＋ افزودن کار یا عادت</button></div>
${header('بخش‌های من','هر کارت صفحه مستقل خودش را دارد')}<div class="grid module-grid">${moduleCards.map(m=>`<button class="card module-card" data-open-module="${m.id}"><div class="stat-icon">${moduleIcon(m)}</div><b>${esc(m.title)}</b><div class="muted small">${m.kind==='study'?'مطالعه و تست':m.kind==='internship'?'فعالیت‌ها و گزارش':m.kind==='goals'?'پیگیری هدف‌ها':`${(state.moduleEntries[m.id]||[]).length} مورد ثبت‌شده`}</div></button>`).join('')}<button class="card module-card add-module-card" data-go="modules"><div class="stat-icon">＋</div><b>مدیریت کارت‌ها</b><div class="muted small">افزودن یا ویرایش بخش‌ها</div></button></div>`}
function daily(){const ts=activeTasks(selectedDate);return `${header('روزانه','کارها و عادت‌ها را برای هر روز مدیریت کن')}<div class="card"><div class="field"><label>روز موردنظر</label><input type="date" id="dailyDate" value="${selectedDate}" /></div><div class="metric-row"><span>پیشرفت این روز</span><b>${faNum(taskPercent(selectedDate))}٪</b></div><div class="progress-track"><span style="width:${taskPercent(selectedDate)}%"></span></div>${ts.length?ts.map(t=>taskHTML(t,selectedDate)).join(''):'<div class="empty">برای این روز کاری نداری؛ یک عادت جدید اضافه کن.</div>'}<button class="add-btn" data-add-task>＋ افزودن کار یا عادت</button></div>${header('مدیریت کارها','هر کار به دسته‌بندی مربوط خودش وصل می‌شود')}<div class="card">${state.tasks.map(t=>`<div class="task-row"><div class="task-content"><div class="task-title">${esc(t.title)} ${t.active===false?'<span class="tag">غیرفعال</span>':''}</div><div class="task-meta">${esc(t.category||'شخصی')} · ${t.repeat==='daily'?'هر روز':t.repeat==='selected'?'روزهای انتخابی':'یک‌باره'} ${t.time?'· '+esc(t.time):''}${t.alarm?' · 🔔 زنگ فعال':''}</div></div><button class="icon-btn" data-edit-task="${t.id}">✎</button><button class="icon-btn" data-delete-task="${t.id}" aria-label="حذف">×</button></div>`).join('')||'<div class="empty">هنوز کاری اضافه نشده.</div>'}</div>`}
function jalaliParts(date){const parts=new Intl.DateTimeFormat('en-u-ca-persian',{year:'numeric',month:'numeric',day:'numeric'}).formatToParts(date);const get=t=>Number(parts.find(p=>p.type===t)?.value);return {year:get('year'),month:get('month'),day:get('day')};}
function jalaliMonthName(date){return new Intl.DateTimeFormat('fa-IR-u-ca-persian',{month:'long',year:'numeric'}).format(date)}
function changeJalaliMonth(delta){const base=jalaliParts(calendarMonth);let anchor=new Date(calendarMonth);for(let i=-20;i<=20;i++){const d=new Date(calendarMonth);d.setDate(calendarMonth.getDate()+i);const p=jalaliParts(d);if(p.year===base.year&&p.month===base.month&&p.day===15){anchor=d;break;}}anchor.setDate(anchor.getDate()+delta*30);calendarMonth=anchor;}
function calendar(){const base=jalaliParts(calendarMonth),firstSearch=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()-1,1);let first=null;for(let i=0;i<100;i++){const d=new Date(firstSearch);d.setDate(firstSearch.getDate()+i);const p=jalaliParts(d);if(p.year===base.year&&p.month===base.month&&p.day===1){first=d;break;}}if(!first)first=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth(),1);let dates=[];for(let i=0;i<32;i++){const d=new Date(first);d.setDate(first.getDate()+i);const p=jalaliParts(d);if(i>0&&(p.year!==base.year||p.month!==base.month))break;dates.push({date:iso(d),day:p.day,dow:d.getDay()});}const offset=(first.getDay()+1)%7;let cells='';for(let i=0;i<offset;i++)cells+='<div class="calendar-empty"></div>';for(const x of dates){const count=activeTasks(x.date).length,completed=activeTasks(x.date).filter(t=>doneToday(t,x.date)).length;cells+=`<button class="day-cell ${x.date===today?'today':''} ${x.date===selectedDate?'selected':''} ${count?'has-task':''}" data-date-select="${x.date}"><span>${faNum(x.day)}</span>${count?`<small>${faNum(completed)}/${faNum(count)}</small>`:''}</button>`;}return `${header('تقویم','تقویم شمسی با نشانگر کارهای هر روز')}<div class="card calendar-card"><div class="section-head calendar-title"><button class="icon-btn" data-month="-1" aria-label="ماه قبل">‹</button><h3>${jalaliMonthName(calendarMonth)}</h3><button class="icon-btn" data-month="1" aria-label="ماه بعد">›</button></div><div class="calendar-grid weekday-grid">${['ش','ی','د','س','چ','پ','ج'].map(x=>`<div>${x}</div>`).join('')}</div><div class="calendar-grid">${cells}</div><div class="calendar-legend"><span><i></i> روز دارای برنامه</span><span><i class="legend-today"></i> امروز</span></div></div>${header('برنامه '+faDate(new Date(selectedDate+'T12:00:00')))}<div class="card">${activeTasks(selectedDate).map(t=>taskHTML(t,selectedDate)).join('')||'<div class="empty">کاری برای این روز ثبت نشده.</div>'}<button class="add-btn" data-add-task>＋ افزودن کار برای این روز</button></div>`}
function studyMinutesToday(){return state.study.filter(x=>x.date===today).reduce((a,x)=>a+Number(x.minutes||0),0)}
function study(){const total=state.study.reduce((a,x)=>a+Number(x.minutes||0),0),tests=state.study.reduce((a,x)=>a+Number(x.tests||0),0);return `${header('کنکور و مطالعه','مطالعه، تست و مرور را با آمار دنبال کن')}<div class="grid"><div class="card stat-card"><div class="stat-icon">⏱</div><div class="stat-value">${faNum(Math.round(total/60*10)/10)}</div><div class="stat-label">مجموع ساعت مطالعه</div></div><div class="card stat-card"><div class="stat-icon">✍️</div><div class="stat-value">${faNum(tests)}</div><div class="stat-label">مجموع تست ثبت‌شده</div></div></div><div class="card"><h3 style="margin-top:0">ثبت جلسه مطالعه</h3><form id="studyForm"><div class="field"><label>درس</label><input name="subject" required placeholder="مثلاً الگوریتم و ساختمان داده" /></div><div class="grid"><div class="field"><label>مدت (دقیقه)</label><input name="minutes" type="number" min="1" required placeholder="۶۰" /></div><div class="field"><label>تعداد تست</label><input name="tests" type="number" min="0" value="0" /></div></div><div class="grid"><div class="field"><label>پاسخ درست</label><input name="correct" type="number" min="0" value="0" /></div><div class="field"><label>تاریخ</label><input name="date" type="date" value="${today}" required /></div></div><div class="field"><label>یادداشت / مبحث</label><textarea name="note" placeholder="چه مبحثی خواندی؟ چه چیزی باید مرور شود؟"></textarea></div><button class="btn primary full">ثبت جلسه</button></form></div>${header('جلسه‌های اخیر')}<div class="card">${state.study.slice().reverse().slice(0,20).map(x=>`<div class="task-row"><div class="task-content"><div class="task-title">${esc(x.subject)}</div><div class="task-meta">${esc(x.date)} · ${faNum(x.minutes)} دقیقه · ${faNum(x.tests||0)} تست ${x.tests?`· ${faNum(Math.round((x.correct||0)/x.tests*100))}٪ درست`:''}</div>${x.note?`<div class="task-meta">${esc(x.note)}</div>`:''}</div><button class="icon-btn" data-delete-study="${x.id}">×</button></div>`).join('')||'<div class="empty">هنوز جلسه‌ای ثبت نکردی.</div>'}</div>`}
function internship(){const total=state.internship.reduce((a,x)=>a+Number(x.minutes||0),0);return `${header('گزارش کارآموزی','ثبت کن چه کردی، چه یاد گرفتی و چقدر زمان گذاشتی')}<div class="grid"><div class="card stat-card"><div class="stat-icon">🧾</div><div class="stat-value">${faNum(state.internship.length)}</div><div class="stat-label">فعالیت ثبت‌شده</div></div><div class="card stat-card"><div class="stat-icon">⌛</div><div class="stat-value">${faNum(Math.round(total/60*10)/10)}</div><div class="stat-label">ساعت ثبت‌شده</div></div></div><div class="card"><h3 style="margin-top:0">ثبت فعالیت جدید</h3><form id="internForm"><div class="field"><label>عنوان فعالیت</label><input name="title" required placeholder="مثلاً رفع خطای فرم فاکتور فروش" /></div><div class="grid"><div class="field"><label>تاریخ</label><input name="date" type="date" value="${today}" required /></div><div class="field"><label>مدت (دقیقه)</label><input name="minutes" type="number" min="0" value="60" /></div></div><div class="field"><label>نتیجه و چیزی که یاد گرفتم</label><textarea name="note" placeholder="مراحل انجام، علت خطا و راه‌حل"></textarea></div><div class="field"><label>وضعیت</label><select name="status"><option value="done">انجام شد</option><option value="progress">در حال انجام</option><option value="blocked">نیازمند پیگیری</option></select></div><button class="btn primary full">ثبت فعالیت</button></form></div><div class="section-head"><h2>گزارش فعالیت‌ها</h2><button class="text-btn" data-export="internship">خروجی گزارش</button></div><div class="card">${state.internship.slice().reverse().map(x=>`<div class="task-row"><div class="task-content"><div class="task-title">${esc(x.title)}</div><div class="task-meta">${esc(x.date)} · ${faNum(x.minutes)} دقیقه · ${{done:'انجام شد',progress:'در حال انجام',blocked:'نیازمند پیگیری'}[x.status]||'ثبت‌شده'}</div>${x.note?`<div class="task-meta" style="white-space:pre-wrap">${esc(x.note)}</div>`:''}</div><button class="icon-btn" data-delete-intern="${x.id}">×</button></div>`).join('')||'<div class="empty">فعالیت‌هایت را ثبت کن تا آخر ماه گزارش آماده باشد.</div>'}</div>`}
function goals(){return `${header('هدف‌های بلندمدت','هدف را به قدم‌های کوچک و قابل پیگیری تبدیل کن')}<div class="notice">به‌جای هدف کلی، یک قدم مشخص و قابل انجام تعریف کن.</div><button class="add-btn" data-add-goal>＋ افزودن هدف</button><div style="margin-top:14px">${state.goals.map(g=>`<div class="card"><div class="task-row" style="padding-top:0"><div class="task-content"><div class="task-title">${esc(g.title)} ${g.done?'<span class="tag">تمام شد</span>':''}</div>${g.description?`<div class="task-meta">${esc(g.description)}</div>`:''}${g.deadline?`<div class="task-meta">مهلت: ${esc(g.deadline)}</div>`:''}</div><button class="icon-btn" data-delete-goal="${g.id}">×</button></div><div class="metric-row"><span>پیشرفت</span><b>${faNum(g.progress||0)}٪</b></div><input type="range" min="0" max="100" value="${g.progress||0}" data-goal-progress="${g.id}" style="width:100%;accent-color:var(--accent2)"/><button class="btn ${g.done?'secondary':'primary'} full" style="margin-top:12px" data-goal-done="${g.id}">${g.done?'بازگرداندن به هدف‌های فعال':'علامت‌گذاری به‌عنوان تکمیل‌شده'}</button></div>`).join('')||'<div class="card empty">هنوز هدفی تعریف نکردی.</div>'}</div>`}
function modulesPage(){return `${header('بخش‌های من','کارت‌های آماده را انتخاب کن یا بخش شخصی بساز')}<div class="notice success-note">هر کارت صفحه مستقل دارد. کارت‌های کنکور و کارآموزی صفحه اختصاصی خودشان را دارند؛ بقیه کارت‌ها هم دفتر ثبت مستقل دارند.</div><div class="module-toolbar"><button class="btn primary" data-add-module>＋ افزودن کارت آماده</button><button class="btn secondary" data-add-custom-module>＋ ساخت بخش شخصی</button><button class="btn secondary" data-go="settings">تنظیم کارت‌های داشبورد</button></div><div class="grid module-grid">${state.modules.map(m=>`<div class="card module-card managed-module"><div class="module-card-top"><div class="stat-icon">${moduleIcon(m)}</div><div class="module-manage-actions"><button class="icon-btn" data-edit-module="${m.id}" aria-label="ویرایش کارت">✎</button><button class="icon-btn" data-toggle-module="${m.id}" aria-label="نمایش یا پنهان کردن">${m.visible===false?'○':'●'}</button></div></div><b>${esc(m.title)}</b><div class="muted small">${m.kind==='study'?'مطالعه و تست':m.kind==='internship'?'گزارش فعالیت':m.kind==='goals'?'اهداف':`${faNum((state.moduleEntries[m.id]||[]).length)} مورد ثبت‌شده`}</div><button class="module-open" data-open-module="${m.id}">باز کردن بخش ←</button>${m.preset?'<span class="muted small">کارت آماده</span>':`<button class="text-btn" data-delete-module="${m.id}">حذف کارت</button>`}</div>`).join('')}</div>`}
function modulePage(){const m=state.modules.find(x=>x.id===activeModuleId);if(!m)return modulesPage();if(m.kind==='study')return study();if(m.kind==='internship')return internship();if(m.kind==='goals')return goals();const entries=state.moduleEntries[m.id]||[];const related=state.tasks.filter(t=>t.category===m.title);return `${header(`${moduleIcon(m)} ${esc(m.title)}`,'دفتر مستقل این بخش؛ اطلاعات روی همین دستگاه ذخیره می‌شود')}<div class="module-toolbar"><button class="btn primary" data-add-entry="${m.id}">＋ افزودن مورد</button><button class="btn secondary" data-add-module-task="${m.id}">＋ افزودن کار/عادت</button><button class="btn secondary" data-go="modules">همه بخش‌ها</button><button class="icon-btn" data-edit-module="${m.id}" aria-label="ویرایش کارت">✎</button></div>${header('کارها و عادت‌های مرتبط')}<div class="card">${related.map(t=>taskHTML(t)).join('')||'<div class="empty">هنوز کار یا عادتی به این دسته وصل نشده.</div>'}</div>${header('موارد ثبت‌شده')}<div class="card">${entries.slice().reverse().map(x=>`<div class="task-row entry-row"><div class="task-content"><div class="task-title">${esc(x.title)}</div><div class="task-meta">${x.date?faDate(new Date(x.date+'T12:00:00')):''}${x.status?' · '+esc(x.status):''}</div>${x.note?`<div class="task-meta entry-note">${esc(x.note)}</div>`:''}</div><button class="icon-btn" data-edit-entry="${m.id}|${x.id}">✎</button><button class="icon-btn" data-delete-entry="${m.id}|${x.id}">×</button></div>`).join('')||'<div class="empty">هنوز موردی در این بخش ثبت نشده. از «افزودن مورد» شروع کن.</div>'}</div>`}
function profile(){return `${header('پروفایل','اطلاعات شخصی و میانبرهای برنامه')}<div class="card profile-card"><div class="profile-avatar">${esc((state.profile.name||'ر').slice(0,1))}</div><h2>${esc(state.profile.name||'پروفایل من')}</h2><p class="muted small">روز‌یار؛ اطلاعات روی همین دستگاه ذخیره می‌شود.</p><form id="profileForm"><div class="field"><label>نام نمایشی</label><input name="name" value="${esc(state.profile.name||'')}" placeholder="نام کوچک" /></div><button class="btn primary full">ذخیره پروفایل</button></form></div><div class="card"><button class="settings-row" data-go="analytics"><span class="settings-icon">📊</span><span><b>آمار پیشرفت</b><small>نمودار عادت‌ها، مطالعه و اهداف</small></span><span>‹</span></button><button class="settings-row" data-go="search"><span class="settings-icon">🔎</span><span><b>جست‌وجوی سراسری</b><small>پیدا کردن کارها، یادداشت‌ها و گزارش‌ها</small></span><span>‹</span></button><button class="settings-row" data-go="settings"><span class="settings-icon">⚙️</span><span><b>تنظیمات</b><small>تم، اعلان‌ها، آب و کارت‌ها</small></span><span>‹</span></button><button class="settings-row" data-go="modules"><span class="settings-icon">▦</span><span><b>مدیریت کارت‌ها</b><small>افزودن و ویرایش بخش‌ها</small></span><span>‹</span></button><button class="settings-row" data-export="all"><span class="settings-icon">💾</span><span><b>پشتیبان‌گیری</b><small>ذخیره فایل JSON</small></span><span>‹</span></button></div>${header('خلاصه فعالیت')}<div class="card"><div class="metric-row"><span>کارهای انجام‌شده امروز</span><b>${faNum(activeTasks().filter(t=>doneToday(t)).length)}/${faNum(activeTasks().length)}</b></div><div class="metric-row"><span>ساعت مطالعه ثبت‌شده</span><b>${faNum(Math.round(state.study.reduce((a,x)=>a+Number(x.minutes||0),0)/60*10)/10)}</b></div><div class="metric-row"><span>گزارش‌های کارآموزی</span><b>${faNum(state.internship.length)}</b></div></div>`}
function analytics(){
 const days=[]; for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const date=iso(d);const ts=activeTasks(date);days.push({date,label:new Intl.DateTimeFormat('fa-IR-u-ca-persian',{weekday:'short'}).format(d),done:ts.filter(t=>doneToday(t,date)).length,total:ts.length,minutes:state.study.filter(x=>x.date===date).reduce((a,x)=>a+Number(x.minutes||0),0)});}
 const maxM=Math.max(60,...days.map(x=>x.minutes));const totalDone=days.reduce((a,x)=>a+x.done,0),totalTasks=days.reduce((a,x)=>a+x.total,0),totalM=days.reduce((a,x)=>a+x.minutes,0);
 return `${header('آمار پیشرفت','خلاصه عملکرد هفت روز اخیر؛ اطلاعات فقط روی همین دستگاه است')}<div class="grid"><div class="card stat-card"><div class="stat-icon">✅</div><div class="stat-value">${faNum(totalTasks?Math.round(totalDone/totalTasks*100):0)}٪</div><div class="stat-label">نرخ انجام کارها</div></div><div class="card stat-card"><div class="stat-icon">⏱</div><div class="stat-value">${faNum(Math.round(totalM/60*10)/10)}</div><div class="stat-label">ساعت مطالعه</div></div><div class="card stat-card"><div class="stat-icon">🎯</div><div class="stat-value">${faNum(state.goals.filter(g=>g.done).length)}</div><div class="stat-label">هدف تکمیل‌شده</div></div><div class="card stat-card"><div class="stat-icon">📝</div><div class="stat-value">${faNum(state.internship.length)}</div><div class="stat-label">گزارش کارآموزی</div></div></div><div class="card"><h3 class="card-heading">دقایق مطالعه در هفته</h3><div class="chart">${days.map(d=>`<div class="chart-col"><small>${faNum(d.minutes)}</small><span style="height:${Math.max(3,d.minutes/maxM*75)}%"></span><small>${esc(d.label)}</small></div>`).join('')}</div></div><div class="card"><h3 class="card-heading">انجام کارهای روزانه</h3>${days.map(d=>`<div class="metric-row"><span>${esc(d.label)} · ${esc(d.date)}</span><b>${faNum(d.done)} از ${faNum(d.total)}</b></div><div class="progress-track" style="margin-top:0;margin-bottom:10px"><span style="width:${d.total?Math.round(d.done/d.total*100):0}%"></span></div>`).join('')}</div><div class="card"><h3 class="card-heading">پیشرفت هدف‌ها</h3>${state.goals.map(g=>`<div class="metric-row"><span>${esc(g.title)}</span><b>${faNum(g.progress||0)}٪</b></div><div class="progress-track" style="margin-top:0;margin-bottom:10px"><span style="width:${g.progress||0}%"></span></div>`).join('')||'<div class="empty">هنوز هدفی ثبت نشده است.</div>'}</div>`;
}
function searchPage(){return `${header('جست‌وجو','در کارها، جلسه‌های مطالعه، گزارش‌ها و یادداشت‌ها بگرد')}<div class="card"><div class="field"><label for="globalSearch">عبارت جست‌وجو</label><input id="globalSearch" type="search" autocomplete="off" placeholder="مثلاً الگوریتم، باشگاه، گزارش..." /></div><div id="searchResults" class="empty">برای شروع، عبارت موردنظر را بنویس.</div></div>`}
function runSearch(q){const out=$('#searchResults');if(!out)return;const term=q.trim().toLocaleLowerCase('fa');if(!term){out.className='empty';out.textContent='برای شروع، عبارت موردنظر را بنویس.';return;}const hits=[];for(const t of state.tasks)if(`${t.title} ${t.category} ${t.time||''}`.toLocaleLowerCase('fa').includes(term))hits.push({icon:'✓',title:t.title,meta:`کار روزانه · ${t.category||'شخصی'}`});for(const x of state.study)if(`${x.subject} ${x.note||''}`.toLocaleLowerCase('fa').includes(term))hits.push({icon:'📚',title:x.subject,meta:`جلسه مطالعه · ${x.date} · ${x.minutes} دقیقه`});for(const x of state.internship)if(`${x.title} ${x.note||''}`.toLocaleLowerCase('fa').includes(term))hits.push({icon:'📝',title:x.title,meta:`گزارش کارآموزی · ${x.date}`});for(const g of state.goals)if(`${g.title} ${g.description||''}`.toLocaleLowerCase('fa').includes(term))hits.push({icon:'🎯',title:g.title,meta:`هدف · ${g.progress||0}٪ پیشرفت`});for(const m of state.modules)if(`${m.title}`.toLocaleLowerCase('fa').includes(term))hits.push({icon:m.icon||'▦',title:m.title,meta:'بخش شخصی'});for(const [mid,arr] of Object.entries(state.moduleEntries||{})){const m=state.modules.find(x=>x.id===mid);for(const x of arr||[])if(`${x.title} ${x.note||''}`.toLocaleLowerCase('fa').includes(term))hits.push({icon:m?.icon||'▦',title:x.title,meta:`${m?.title||'بخش'} · ${x.date||''}`});}out.className='';out.innerHTML=hits.length?hits.slice(0,60).map(x=>`<div class="task-row"><div class="stat-icon">${esc(x.icon)}</div><div class="task-content"><div class="task-title">${esc(x.title)}</div><div class="task-meta">${esc(x.meta)}</div></div></div>`).join(''):'<div class="empty">نتیجه‌ای پیدا نشد.</div>';}
function settings(){return `${header('تنظیمات','ظاهر و رفتار روزیار را مطابق سلیقه‌ات تغییر بده')}<div class="card"><h3 class="card-heading">ظاهر برنامه</h3><div class="theme-grid">${[{id:'midnight',name:'نیمه‌شب',desc:'سرمه‌ای و بنفش',swatch:['#0b0e15','#9b8cff']},{id:'forest',name:'جنگلی',desc:'سبز تیره و نعنایی',swatch:['#101914','#8bd3a8']},{id:'ocean',name:'اقیانوسی',desc:'آبی نفتی و فیروزه‌ای',swatch:['#0b1720','#67d7e8']},{id:'warm',name:'گرم و خاکی',desc:'قهوه‌ای و کهربایی',swatch:['#1c1714','#e5b778']},{id:'light',name:'روشن',desc:'سفید و بنفش ملایم',swatch:['#f4f5fa','#7768d9']},{id:'rose',name:'رز',desc:'تیره و صورتی',swatch:['#1b1019','#f09ac2']},{id:'slate',name:'خاکستری',desc:'ذغالی و آبی',swatch:['#11151c','#9eb7d8']}].map(t=>`<button class="theme-option ${state.settings.theme===t.id?'selected':''}" data-theme="${t.id}"><span class="theme-swatches"><i style="background:${t.swatch[0]}"></i><i style="background:${t.swatch[1]}"></i></span><b>${t.name}</b><small>${t.desc}</small>${state.settings.theme===t.id?'<span class="theme-check">✓</span>':''}</button>`).join('')}</div><button class="theme-option ${state.settings.theme==='custom'?'selected':''}" data-theme="custom"><span class="theme-swatches"><i style="background:${esc(state.settings.customTheme?.bg||'#10131c')}"></i><i style="background:${esc(state.settings.customTheme?.accent||'#9b8cff')}"></i></span><b>تم سفارشی من</b><small>رنگ‌های دلخواه خودت</small>${state.settings.theme==='custom'?'<span class="theme-check">✓</span>':''}</button></div><div class="card"><h3 class="card-heading">شخصی‌سازی رنگ‌ها</h3><p class="muted small">رنگ پس‌زمینه، کارت‌ها و رنگ تأکیدی را انتخاب کن؛ تغییرات روی همین دستگاه ذخیره می‌شوند.</p><div class="grid">${[['bg','پس‌زمینه'],['panel','رنگ کارت'],['panel2','کارت فرعی'],['line','حاشیه'],['text','متن اصلی'],['muted','متن کم‌رنگ'],['accent','رنگ اصلی'],['accent2','رنگ تأکیدی دوم']].map(([k,label])=>`<div class="field color-field"><label for="custom-${k}">${label}</label><input id="custom-${k}" type="color" value="${esc(state.settings.customTheme?.[k]||({bg:'#10131c',panel:'#1a1f2b',panel2:'#242b3a',line:'#384052',text:'#f3f4fa',muted:'#a6adbd',accent:'#9b8cff',accent2:'#67d7e8'}[k]))}" data-custom-color="${k}" /></div>`).join('')}</div><button class="btn primary full" id="saveCustomTheme">ذخیره و اعمال تم سفارشی</button></div><div class="card"><h3 class="card-heading">آب خوردن</h3><div class="grid"><div class="field"><label>هدف روزانه (لیوان؛ حداکثر ۸)</label><input id="waterGoal" type="number" min="1" max="8" value="${Math.min(8,state.settings.waterGoal)}" /></div><div class="field"><label>حجم هر لیوان (میلی‌لیتر)</label><input id="cupMl" type="number" min="50" max="1000" value="${state.settings.cupMl}" /></div></div><button class="btn secondary full" id="saveWaterSettings">ذخیره تنظیمات آب</button></div><div class="card"><h3 class="card-heading">اعلان و زنگ یادآوری</h3><p class="muted small">می‌توانی صدای آزمایشی داخل برنامه و سطح صدای آن را تنظیم کنی. صدای اعلان در پس‌زمینه تابع کانال اعلان اندروید و تنظیمات گوشی است؛ این کنترل، صدای کل گوشی را تغییر نمی‌دهد و زنگ ممتد مثل ساعت هنوز به پیاده‌سازی بومی جداگانه نیاز دارد.</p><div class="field"><label>صدای آزمایشی</label><select id="alarmTone"><option value="classic" ${state.settings.alarmTone==='classic'?'selected':''}>بیپ کلاسیک</option><option value="double" ${state.settings.alarmTone==='double'?'selected':''}>دو بیپ</option><option value="soft" ${state.settings.alarmTone==='soft'?'selected':''}>صدای ملایم</option></select></div><div class="field"><label>بلندی صدای داخل برنامه: <b id="alarmVolumeLabel">${faNum(state.settings.alarmVolume??70)}٪</b></label><input id="alarmVolume" type="range" min="0" max="100" value="${state.settings.alarmVolume??70}" /></div><button class="btn secondary full" id="previewAlarm">▶ پخش صدای انتخاب‌شده</button><button class="btn primary full" id="enableNotifications">فعال‌کردن اعلان‌ها</button><button class="btn secondary full" id="testNotification" style="margin-top:8px">آزمایش صدای اعلان</button><div class="metric-row"><span>وضعیت اعلان‌ها</span><b>${state.settings.notifications?'فعال':'هنوز فعال نشده'}</b></div><button class="btn secondary full" data-go="daily">مدیریت ساعت زنگ کارها</button></div><div class="card"><h3 class="card-heading">کارت‌های داشبورد</h3><p class="muted small">کارت‌های خانه را روشن/خاموش، ویرایش یا اضافه کن.</p>${state.dashboardCards.map(c=>`<div class="task-row"><div class="stat-icon">${esc(c.icon||'◈')}</div><div class="task-content"><div class="task-title">${esc(c.title)}</div><div class="task-meta">${esc(c.key)}</div></div><button class="icon-btn" data-dash-move="${c.id}|-1" aria-label="انتقال به بالا">↑</button><button class="icon-btn" data-dash-move="${c.id}|1" aria-label="انتقال به پایین">↓</button><button class="icon-btn" data-edit-dash="${c.id}">✎</button><button class="icon-btn" data-toggle-dash="${c.id}">${c.visible===false?'○':'●'}</button><button class="icon-btn" data-delete-dash="${c.id}" aria-label="حذف کارت">×</button></div>`).join('')}<button class="add-btn" data-add-dash>＋ افزودن کارت داشبورد</button></div><div class="card"><h3 class="card-heading">پشتیبان‌گیری و بازیابی</h3><p class="muted small">در اندروید پنجره انتخاب فایل سیستم باز می‌شود تا نام و مسیر ذخیره را خودت انتخاب کنی. در مرورگرهای سازگار هم پنجره انتخاب محل ذخیره نمایش داده می‌شود.</p><button class="btn primary full" data-export="all">💾 انتخاب محل و ذخیره پشتیبان</button><div class="field"><label>بازیابی پشتیبان JSON</label><input type="file" id="importFile" accept="application/json,.json" /></div><button class="btn secondary full" data-export="internship">خروجی گزارش کارآموزی</button></div><div class="card"><h3 class="card-heading">حریم خصوصی و نگهداری داده</h3><div class="notice success-note">همگام‌سازی ابری در این نسخه حذف شده است. اطلاعات فقط در حافظه محلی برنامه ذخیره می‌شود؛ برای انتقال به گوشی دیگر از پشتیبان استفاده کن.</div><button class="btn secondary full danger-btn" id="resetLocal">بازنشانی اطلاعات این دستگاه</button></div>`}
function render(){document.body.dataset.page=page;document.documentElement.dataset.theme=state.settings.theme||'midnight';if(state.settings.theme==='custom'){const c=state.settings.customTheme||{};for(const k of ['bg','panel','panel2','line','text','muted','accent','accent2'])if(c[k])document.documentElement.style.setProperty('--'+k,c[k]);}else{for(const k of ['bg','panel','panel2','line','text','muted','accent','accent2'])document.documentElement.style.removeProperty('--'+k);}const view=$('#view');const pages={home,daily,calendar,study,internship,goals,modules:modulesPage,profile,settings,analytics,search:searchPage};view.innerHTML=page==='module'?modulePage():(pages[page]||home)();document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page||(page==='module'&&b.dataset.page==='modules')));}
function openModal(title,html,onSave){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;const dlg=$('#modal');const form=$('#modalForm');form.onsubmit=e=>{if(e.submitter?.value==='cancel'){e.preventDefault();dlg.close();return;}e.preventDefault();const fd=new FormData(form);if(onSave(fd)===false)return;dlg.close();render()};dlg.showModal();}
const categoryOptions=()=>[...new Set(['روزانه','سلامت','سلامت و ورزش','کار','کنکور و مطالعه','شخصی','یادگیری','خانواده',...state.modules.map(m=>m.title)])];
function taskModal(id,presetCategory){const old=state.tasks.find(t=>t.id===id);const t=old||{title:'',category:presetCategory||'شخصی',time:'',repeat:'daily',days:[0,1,2,3,4,5,6],active:true,alarm:false};openModal(old?'ویرایش کار':'افزودن کار یا عادت',`<div class="field"><label>عنوان</label><input name="title" maxlength="90" value="${esc(t.title)}" placeholder="مثلاً باشگاه رفتن" /></div><div class="field"><label>دسته‌بندی / بخش</label><select name="category">${categoryOptions().map(c=>`<option ${t.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><small class="muted">برای ثبت جزئیات هر دسته، کارت همان بخش را از «بخش‌های من» باز کن.</small></div><div class="field"><label>ساعت (برای زنگ یادآوری)</label><input name="time" type="time" value="${esc(t.time||'')}" /></div><div class="field"><label>تکرار</label><select name="repeat"><option value="daily" ${t.repeat==='daily'?'selected':''}>هر روز</option><option value="selected" ${t.repeat==='selected'?'selected':''}>روزهای انتخابی هفته</option><option value="once" ${t.repeat==='once'?'selected':''}>فقط یک روز</option></select></div><div class="field"><label>روزهای هفته (برای «روزهای انتخابی»)</label><div class="day-chips">${[[6,'ش'],[0,'ی'],[1,'د'],[2,'س'],[3,'چ'],[4,'پ'],[5,'ج']].map(([n,l])=>`<label class="day-chip"><input type="checkbox" name="d" value="${n}" ${(t.days||[0,1,2,3,4,5,6]).includes(n)?'checked':''}/><span>${l}</span></label>`).join('')}</div></div><div class="field"><label>تاریخ (برای کار یک‌باره)</label><input name="date" type="date" value="${t.date||selectedDate}" /></div><label class="toggle-line"><input name="alarm" type="checkbox" ${t.alarm?'checked':''}/> زنگ یادآوری برای این کار فعال باشد</label><label class="toggle-line"><input name="active" type="checkbox" ${t.active!==false?'checked':''}/> این کار فعال باشد</label>`,fd=>{const title=String(fd.get('title')||'').trim();if(!title){toast('عنوان کار را وارد کن یا انصراف را بزن');return false;}if(fd.get('repeat')==='selected'&&!fd.getAll('d').length){toast('حداقل یک روز هفته را انتخاب کن');return false;}if(fd.get('alarm')==='on'&&!fd.get('time')){toast('برای زنگ یادآوری، ساعت را وارد کن');return false;}const item={...t,title,category:fd.get('category'),time:fd.get('time'),repeat:fd.get('repeat'),days:fd.getAll('d').map(Number),date:fd.get('date'),active:fd.get('active')==='on',alarm:fd.get('alarm')==='on',completedDates:t.completedDates||[]};if(old)state.tasks=state.tasks.map(x=>x.id===id?item:x);else state.tasks.push({id:uid(),...item});save();if(state.settings.notifications)setupAlarms();if(item.alarm&&!state.settings.notifications)toast('کار ذخیره شد؛ برای فعال‌شدن زنگ، اعلان‌ها را از تنظیمات فعال کن');else toast(old?'کار ویرایش شد':'کار اضافه شد');});}
function goalModal(){openModal('افزودن هدف',`<div class="field"><label>عنوان هدف</label><input name="title" placeholder="مثلاً ساخت یک پروژه واقعی" /></div><div class="field"><label>توضیح و قدم بعدی</label><textarea name="description" placeholder="اولین قدم قابل انجام چیست؟"></textarea></div><div class="field"><label>مهلت (اختیاری)</label><input name="deadline" type="date" /></div>`,fd=>{const title=String(fd.get('title')||'').trim();if(!title){toast('عنوان هدف را وارد کن');return false;}state.goals.push({id:uid(),title,description:String(fd.get('description')||'').trim(),deadline:fd.get('deadline'),progress:0,done:false});save();toast('هدف اضافه شد')})}
function moduleModal(id){const old=state.modules.find(x=>x.id===id);const m=old||{title:'',icon:'✨',kind:'module',visible:true};openModal(old?'ویرایش کارت':'افزودن کارت جدید',`<div class="field"><label>نام بخش</label><input name="title" value="${esc(m.title)}" placeholder="مثلاً زبان انگلیسی" /></div><div class="field"><label>آیکون (ایموجی)</label><input name="icon" maxlength="6" value="${esc(m.icon)}" placeholder="📘" /></div><div class="field"><label>نوع بخش</label><select name="kind"><option value="module" ${m.kind==='module'?'selected':''}>دفتر عمومی با ثبت مورد</option><option value="study" ${m.kind==='study'?'selected':''}>صفحه کنکور و مطالعه</option><option value="internship" ${m.kind==='internship'?'selected':''}>صفحه گزارش کارآموزی</option><option value="goals" ${m.kind==='goals'?'selected':''}>صفحه هدف‌ها</option></select></div><label class="toggle-line"><input name="visible" type="checkbox" ${m.visible!==false?'checked':''}/> در خانه نمایش داده شود</label>`,fd=>{const title=String(fd.get('title')||'').trim();if(!title){toast('نام کارت را وارد کن');return false;}if(old){Object.assign(old,{title,icon:String(fd.get('icon')||'◈').trim(),kind:fd.get('kind'),visible:fd.get('visible')==='on'});}else{const key='custom-'+uid();state.modules.push({id:key,key,title,icon:String(fd.get('icon')||'◈').trim(),kind:fd.get('kind'),visible:fd.get('visible')==='on',preset:false,order:state.modules.length});}save();toast(old?'کارت ویرایش شد':'کارت اضافه شد')})}
function moduleIcon(m){return m&&['study','internship','health','finance','reading','projects','goals'].includes(m.key)?iconSvg(m.key):esc(m?.icon||'◈')}
function iconSvg(name){
 const paths={
  study:'<path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v16H6.5A2.5 2.5 0 0 0 4 21z"/><path d="M4 5.5V21M8 7h8M8 11h8"/>',
  internship:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4m8-4v4M8 11h8M8 15h5"/>',
  health:'<path d="M20.8 8.8c0 5.1-8.8 10-8.8 10s-8.8-4.9-8.8-10A4.8 4.8 0 0 1 12 6.4a4.8 4.8 0 0 1 8.8 2.4Z"/><path d="M3.5 12h4l2-3 3.2 6 2-3h5.8"/>',
  finance:'<rect x="3" y="6" width="18" height="14" rx="2"/><path d="M3 10h18M7 16h4M7 3h10"/>',
  reading:'<path d="M12 7v14M12 7C9 4 5 4 3 5v14c3-1 6-1 9 2M12 7c3-3 7-3 9-2v14c-3-1-6-1-9 2"/>',
  projects:'<rect x="3" y="3" width="8" height="8" rx="2"/><rect x="13" y="3" width="8" height="5" rx="2"/><rect x="13" y="10" width="8" height="11" rx="2"/><rect x="3" y="13" width="8" height="8" rx="2"/>',
  goals:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/><path d="m14 10 6-6"/>',
  home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7h-6v7H4a1 1 0 0 1-1-1z"/>',
  daily:'<path d="m5 12 4 4L19 6"/><path d="M20 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h10"/>',
  calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18M8 14h2m4 0h2m-8 3h2"/>',
  modules:'<rect x="3" y="3" width="8" height="8" rx="2"/><rect x="13" y="3" width="8" height="8" rx="2"/><rect x="3" y="13" width="8" height="8" rx="2"/><rect x="13" y="13" width="8" height="8" rx="2"/>',
  profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>'
 };
 return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.projects}</svg>`;
}
function addPresetModal(){
 const items=PRESETS.map(p=>{
  const existing=state.modules.find(m=>m.key===p.key||m.id===p.key);
  const action=existing?(existing.visible===false?'فعال‌سازی دوباره':'اضافه شده'):'افزودن کارت';
  const disabled=!!existing&&existing.visible!==false;
  return `<button type="button" class="preset-row ${disabled?'preset-added':''}" data-select-preset="${p.key}" ${disabled?'disabled':''}><span class="preset-icon">${iconSvg(p.key)}</span><span><b>${esc(p.title)}</b><small>${p.kind==='study'?'ثبت مطالعه و تست':p.kind==='internship'?'ثبت گزارش فعالیت':p.kind==='goals'?'پیگیری هدف‌ها':'صفحه مستقل برای ثبت موارد'}</small></span><span class="preset-action">${disabled?'✓':existing?'فعال‌سازی':'＋ افزودن'}</span></button>`;
 }).join('');
 openModal('افزودن کارت آماده',`<p class="muted small preset-intro">کارت موردنظرت را انتخاب کن. کارت‌های قبلی را هم می‌توانی دوباره فعال کنی.</p><div class="preset-list">${items}</div><button type="button" class="btn secondary full" data-add-custom-module>＋ ساخت بخش شخصی</button>`,()=>false);
}
function entryModal(moduleId,entryId){const m=state.modules.find(x=>x.id===moduleId);const arr=state.moduleEntries[moduleId]||[];const old=arr.find(x=>x.id===entryId);const x=old||{title:'',date:today,note:'',status:'در حال انجام'};openModal(old?'ویرایش مورد':'افزودن مورد به '+m.title,`<div class="field"><label>عنوان</label><input name="title" value="${esc(x.title)}" placeholder="عنوان مورد" /></div><div class="field"><label>تاریخ</label><input name="date" type="date" value="${x.date||today}" /></div><div class="field"><label>توضیحات / نتیجه</label><textarea name="note" placeholder="یادداشت، جزئیات یا نتیجه">${esc(x.note||'')}</textarea></div><div class="field"><label>وضعیت</label><select name="status">${['برنامه‌ریزی‌شده','در حال انجام','انجام شد','نیازمند پیگیری'].map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`).join('')}</select></div>`,fd=>{const title=String(fd.get('title')||'').trim();if(!title){toast('عنوان را وارد کن یا انصراف را بزن');return false;}state.moduleEntries[moduleId]=state.moduleEntries[moduleId]||[];const item={...x,title,date:fd.get('date')||today,note:String(fd.get('note')||'').trim(),status:fd.get('status')};if(old)state.moduleEntries[moduleId]=arr.map(y=>y.id===entryId?item:y);else state.moduleEntries[moduleId].push({id:uid(),...item});save();toast(old?'مورد ویرایش شد':'مورد ثبت شد')})}
function dashModal(id){const old=state.dashboardCards.find(c=>c.id===id);const c=old||{title:'',icon:'✨',key:'custom',visible:true};openModal(old?'ویرایش کارت داشبورد':'افزودن کارت داشبورد',`<div class="field"><label>عنوان کارت</label><input name="title" value="${esc(c.title)}" placeholder="مثلاً تعداد تمرین‌های امروز" /></div><div class="field"><label>آیکون</label><input name="icon" value="${esc(c.icon)}" maxlength="6" /></div><div class="field"><label>مقدار کارت</label><select name="key">${[['studyMinutes','دقیقه مطالعه امروز'],['water','لیوان آب امروز'],['internship','فعالیت کاری امروز'],['goals','هدف‌های فعال'],...state.modules.filter(m=>m.kind==='module').map(m=>['module:'+m.id,'تعداد موارد امروز: '+m.title])].map(([k,l])=>`<option value="${esc(k)}" ${c.key===k?'selected':''}>${esc(l)}</option>`).join('')}</select></div><label class="toggle-line"><input name="visible" type="checkbox" ${c.visible!==false?'checked':''}/> نمایش در داشبورد</label>`,fd=>{const title=String(fd.get('title')||'').trim();if(!title){toast('عنوان کارت را وارد کن');return false;}if(old)Object.assign(old,{title,icon:String(fd.get('icon')||'◈'),key:fd.get('key'),visible:fd.get('visible')==='on'});else state.dashboardCards.push({id:uid(),title,icon:String(fd.get('icon')||'◈'),key:fd.get('key'),visible:fd.get('visible')==='on'});save();toast(old?'کارت داشبورد ویرایش شد':'کارت داشبورد اضافه شد')})}
async function exportData(kind){const data=kind==='internship'?state.internship:state;const filename=kind==='internship'?'roozyar-internship.json':`roozyar-backup-${today}.json`;const content=JSON.stringify(data,null,2);const blob=new Blob([content],{type:'application/json;charset=utf-8'});try{const nativeSave=window.RoozYarSaveFile;if(window.Capacitor?.isNativePlatform?.()&&nativeSave?.save){await nativeSave.save({fileName:filename,content});toast('پشتیبان در محل انتخاب‌شده ذخیره شد');return;}}catch(e){if(String(e?.message||'').toLowerCase().includes('cancel')){toast('ذخیره لغو شد؛ هیچ فایلی ایجاد نشد');return;}console.warn(e);toast('انتخاب مسیر انجام نشد؛ دانلود جایگزین می‌شود')}try{if(window.showSaveFilePicker){const handle=await window.showSaveFilePicker({suggestedName:filename,types:[{description:'فایل پشتیبان روزیار',accept:{'application/json':['.json']}}]});const writable=await handle.createWritable();await writable.write(blob);await writable.close();toast('پشتیبان در مسیر انتخابی ذخیره شد');return;}}catch(e){if(e.name==='AbortError'){toast('ذخیره لغو شد؛ هیچ فایلی ایجاد نشد');return;}console.warn(e)}const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('دانلود آغاز شد؛ فایل را در پوشه Downloads بررسی کن');}
async function enableNotifications(){const plugin=window.RoozYarLocalNotifications||window.Capacitor?.Plugins?.LocalNotifications;if(plugin){try{const p=await plugin.requestPermissions();state.settings.notifications=p.display==='granted';save();await setupAlarms();toast(state.settings.notifications?'اعلان‌ها فعال شدند':'مجوز اعلان داده نشد');render();return;}catch(e){console.warn(e)}}if('Notification' in window){const p=await Notification.requestPermission();state.settings.notifications=p==='granted';save();toast(state.settings.notifications?'مجوز اعلان فعال شد؛ یادآوری پس‌زمینه به پشتیبانی نسخه اندروید نیاز دارد':'مجوز اعلان داده نشد');render();return;}toast('نسخه نصب‌شده هنوز رابط اعلان اندروید را در دسترس نگذاشته است.');}

// تابع تست اعلان با استفاده از پلاگین زنگ ممتد
async function testNotification() {
  if (!RoozYarAlarm) {
    toast('این قابلیت فقط در نسخه اندروید کار می‌کند');
    return;
  }
  try {
    await RoozYarAlarm.playAlarm();
    toast('🔔 زنگ در حال پخش است...');
    setTimeout(async () => {
      if (confirm("⏰ زمان بیدار شدن یا انجام کار است!\n\nبرای قطع کردن صدا، تایید کنید.")) {
        try {
          await RoozYarAlarm.stopAlarm();
          toast('زنگ قطع شد.');
        } catch(e) { console.error(e); }
      }
    }, 2000);
  } catch (e) {
    toast('خطا در پخش زنگ: ' + e.message);
  }
}

async function setupAlarms(){const plugin=window.RoozYarLocalNotifications||window.Capacitor?.Plugins?.LocalNotifications;if(!plugin||!state.settings.notifications)return;try{if(plugin.createChannel)await plugin.createChannel({id:'roozyar-reminders-v2',name:'زنگ‌های روزیار',description:'یادآوری کارها و عادت‌ها',importance:5,visibility:1,vibration:true,lights:true});const pending=await plugin.getPending();if(pending.notifications?.length)await plugin.cancel({notifications:pending.notifications.map(n=>({id:n.id}))});const notifications=[];const start=new Date();for(let offset=0;offset<30;offset++){const d=new Date(start);d.setDate(start.getDate()+offset);const date=iso(d);for(const t of state.tasks){if(!t.alarm||!t.active||!t.time)continue;const dow=d.getDay();const applies=t.repeat==='daily'||(t.repeat==='selected'&&(t.days||[]).includes(dow))||(t.repeat==='once'&&t.date===date);if(!applies)continue;const [h,m]=t.time.split(':').map(Number);const at=new Date(d);at.setHours(h,m,0,0);if(at<=start)continue;const id=Math.abs(hashCode(`${t.id}-${date}`))%2147483000+1;notifications.push({id,title:'⏰ '+t.title,body:'زمان انجام این کار رسیده است.',schedule:{at,allowWhileIdle:true},channelId:'roozyar-reminders-v2',extra:{taskId:t.id,date}})}}if(notifications.length)await plugin.schedule({notifications});}catch(e){console.warn('Notification scheduling failed',e)}}
let alarmPreviewTimer=null;
function playAlarmPreview(){try{if(alarmPreviewTimer)clearTimeout(alarmPreviewTimer);const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx){toast('مرورگر پخش صدای آزمایشی را پشتیبانی نمی‌کند');return;}const ctx=new Ctx(),volume=Math.max(0,Math.min(1,Number(state.settings.alarmVolume??70)/100));const tone=state.settings.alarmTone||'classic';const notes=tone==='double'?[880,660]:tone==='soft'?[440,554,440]:[880];let start=ctx.currentTime;for(let r=0;r<3;r++){for(const hz of notes){const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type=tone==='soft'?'sine':'square';osc.frequency.value=hz;gain.gain.setValueAtTime(0.0001,start);gain.gain.exponentialRampToValueAtTime(Math.max(.0002,volume*.22),start+.025);gain.gain.setValueAtTime(Math.max(.0002,volume*.22),start+.16);gain.gain.exponentialRampToValueAtTime(.0001,start+.22);osc.connect(gain);gain.connect(ctx.destination);osc.start(start);osc.stop(start+.24);start+=.28;}start+=.22;}alarmPreviewTimer=setTimeout(()=>ctx.close().catch(()=>{}),Math.max(500,(start-ctx.currentTime)*1000+250));toast('صدای آزمایشی پخش شد');}catch(e){console.warn(e);toast('برای پخش صدا یک‌بار دیگر روی دکمه بزن');}}
function hashCode(s){let h=0;for(let i=0;i<s.length;i++)h=((h<<5)-h)+s.charCodeAt(i)|0;return h;}
function bindEvents(){document.body.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)setPage(b.dataset.page);if(b.dataset.go)setPage(b.dataset.go);if(b.hasAttribute('data-add-task'))taskModal();if(b.dataset.editTask)taskModal(b.dataset.editTask);if(b.dataset.deleteTask){if(confirm('این کار حذف شود؟')){state.tasks=state.tasks.filter(t=>t.id!==b.dataset.deleteTask);save();setupAlarms();render()}}if(b.dataset.waterAdd){state.water[today]=Math.min(8,Math.max(0,waterCount()+Number(b.dataset.waterAdd)));save();render()}if(b.dataset.water){state.water[today]=Math.min(8,Math.max(0,Number(b.dataset.water)));save();render()}if(b.dataset.dateSelect){selectedDate=b.dataset.dateSelect;page='calendar';render()}if(b.dataset.month){changeJalaliMonth(Number(b.dataset.month));render()}if(b.hasAttribute('data-add-goal'))goalModal();if(b.dataset.deleteGoal){state.goals=state.goals.filter(g=>g.id!==b.dataset.deleteGoal);save();render()}if(b.dataset.goalDone){const g=state.goals.find(g=>g.id===b.dataset.goalDone);if(g){g.done=!g.done;g.progress=g.done?100:Math.min(99,g.progress||0);save();render()}}if(b.dataset.deleteStudy){state.study=state.study.filter(x=>x.id!==b.dataset.deleteStudy);save();render()}if(b.dataset.deleteIntern){state.internship=state.internship.filter(x=>x.id!==b.dataset.deleteIntern);save();render()}if(b.dataset.export)exportData(b.dataset.export);if(b.dataset.openModule){activeModuleId=b.dataset.openModule;page='module';render()}if(b.dataset.addModule)addPresetModal();if(b.dataset.selectPreset){const preset=PRESETS.find(p=>p.key===b.dataset.selectPreset);if(preset){let existing=state.modules.find(m=>m.key===preset.key||m.id===preset.key);if(existing){if(existing.visible!==false){toast('این کارت از قبل فعال است');return;}existing.visible=true;}else{state.modules.push({...preset,id:preset.key,visible:true,order:state.modules.length});}save();if($('#modal').open)$('#modal').close();page='modules';render();toast(existing?'کارت دوباره فعال شد':'کارت آماده اضافه شد');}}if(b.hasAttribute('data-add-custom-module')){if($('#modal').open)$('#modal').close();moduleModal()}if(b.dataset.editModule)moduleModal(b.dataset.editModule);if(b.dataset.toggleModule){const m=state.modules.find(x=>x.id===b.dataset.toggleModule);if(m){m.visible=m.visible===false;save();render()}}if(b.dataset.deleteModule){if(confirm('این کارت حذف شود؟ موارد ثبت‌شده آن نیز حذف می‌شوند.')){state.modules=state.modules.filter(x=>x.id!==b.dataset.deleteModule);delete state.moduleEntries[b.dataset.deleteModule];state.dashboardCards=state.dashboardCards.filter(x=>x.key!=='module:'+b.dataset.deleteModule);save();page='modules';render()}}if(b.dataset.addModuleTask){const m=state.modules.find(x=>x.id===b.dataset.addModuleTask);taskModal(undefined,m?.title)}if(b.dataset.addEntry)entryModal(b.dataset.addEntry);if(b.dataset.editEntry){const [mid,eid]=b.dataset.editEntry.split('|');entryModal(mid,eid)}if(b.dataset.deleteEntry){const [mid,eid]=b.dataset.deleteEntry.split('|');if(confirm('این مورد حذف شود؟')){state.moduleEntries[mid]=(state.moduleEntries[mid]||[]).filter(x=>x.id!==eid);save();render()}}if(b.dataset.dashMove){const [id,delta]=b.dataset.dashMove.split('|');const i=state.dashboardCards.findIndex(c=>c.id===id),j=i+Number(delta);if(i>=0&&j>=0&&j<state.dashboardCards.length){const a=state.dashboardCards[i];state.dashboardCards[i]=state.dashboardCards[j];state.dashboardCards[j]=a;save();render()}}if(b.dataset.editDash)dashModal(b.dataset.editDash);if(b.hasAttribute('data-add-dash'))dashModal();if(b.dataset.toggleDash){const c=state.dashboardCards.find(x=>x.id===b.dataset.toggleDash);if(c){c.visible=c.visible===false;save();render()}}if(b.dataset.deleteDash){if(confirm('این کارت از داشبورد حذف شود؟')){state.dashboardCards=state.dashboardCards.filter(x=>x.id!==b.dataset.deleteDash);save();render()}}if(b.id==='saveWaterSettings'){state.settings.waterGoal=Math.max(1,Math.min(8,Number($('#waterGoal').value)||8));state.settings.cupMl=Math.max(50,Math.min(1000,Number($('#cupMl').value)||250));save();toast('تنظیمات ذخیره شد');render()}if(b.id==='enableNotifications')enableNotifications();if(b.id==='testNotification')testNotification();if(b.id==='previewAlarm'){state.settings.alarmTone=$('#alarmTone')?.value||'classic';state.settings.alarmVolume=Number($('#alarmVolume')?.value??70);save();playAlarmPreview();}if(b.id==='saveCustomTheme'){state.settings.customTheme={...state.settings.customTheme};for(const el of document.querySelectorAll('[data-custom-color]'))state.settings.customTheme[el.dataset.customColor]=el.value;state.settings.theme='custom';save();render();toast('تم سفارشی ذخیره و اعمال شد')}if(b.dataset.theme){state.settings.theme=b.dataset.theme;save();render();toast('تم تغییر کرد')}if(b.id==='resetLocal'){if(confirm('اطلاعات ذخیره‌شده روی این دستگاه حذف شود؟ قبلش پشتیبان بگیر.')){localStorage.removeItem('roozyar-state-v1');state=defaultState();save();render();toast('اطلاعات دستگاه بازنشانی شد')}}});
 document.body.addEventListener('change',e=>{const el=e.target;if(el.id==='alarmTone'||el.id==='alarmVolume'){state.settings.alarmTone=$('#alarmTone')?.value||state.settings.alarmTone;state.settings.alarmVolume=Number($('#alarmVolume')?.value??state.settings.alarmVolume);save();const lab=$('#alarmVolumeLabel');if(lab)lab.textContent=faNum(state.settings.alarmVolume)+'٪';}if(el.matches('[data-check]')){const t=state.tasks.find(t=>t.id===el.dataset.check);if(t){const d=el.dataset.date;t.completedDates=t.completedDates||[];t.completedDates=el.checked?[...new Set([...t.completedDates,d])]:t.completedDates.filter(x=>x!==d);save();render();if(el.checked&&d===today&&taskPercent(d)===100)toast('آفرین! همه‌ی کارهای امروز انجام شد 🎉')}}if(el.id==='dailyDate'){selectedDate=el.value||today;render()}if(el.id==='importFile'&&el.files?.[0]){const reader=new FileReader();reader.onload=()=>{try{const d=JSON.parse(reader.result);if(!d.tasks||!d.settings)throw new Error('invalid');if(confirm('اطلاعات فعلی با نسخه پشتیبان جایگزین شود؟')){state={...defaultState(),...d,settings:{...defaultState().settings,...d.settings},modules:d.modules||PRESETS.filter(x=>['study','internship','goals'].includes(x.key)).map((x,i)=>({...x,id:x.key,visible:true,order:i})),moduleEntries:d.moduleEntries||{},dashboardCards:d.dashboardCards||DEFAULT_DASH};delete state.firebaseConfig;save();render();toast('پشتیبان بازیابی شد')}}catch{toast('فایل پشتیبان معتبر نیست')} };reader.readAsText(el.files[0])}});
 document.body.addEventListener('input',e=>{const el=e.target;if(el.id==='globalSearch'){runSearch(el.value)}if(el.id==='alarmVolume'){const lab=$('#alarmVolumeLabel');if(lab)lab.textContent=faNum(Number(el.value))+'٪';}if(el.matches('[data-custom-color]')){document.documentElement.style.setProperty('--'+el.dataset.customColor,el.value);document.documentElement.dataset.theme='custom';}if(el.dataset.goalProgress){const g=state.goals.find(g=>g.id===el.dataset.goalProgress);if(g){g.progress=Number(el.value);g.done=g.progress===100;save();const label=el.closest('.card')?.querySelector('.metric-row b');if(label)label.textContent=faNum(g.progress)+'٪'}}});
 document.body.addEventListener('submit',e=>{const f=e.target;if(!['studyForm','internForm','profileForm'].includes(f.id))return;e.preventDefault();const fd=new FormData(f);if(f.id==='studyForm'){const tests=Number(fd.get('tests')||0),correct=Number(fd.get('correct')||0),minutes=Number(fd.get('minutes')||0);if(correct>tests){toast('تعداد پاسخ درست نمی‌تواند بیشتر از تعداد تست باشد');return}if(!String(fd.get('subject')||'').trim()||minutes<1){toast('درس و مدت مطالعه را وارد کن');return}state.study.push({id:uid(),subject:String(fd.get('subject')).trim(),minutes,tests,correct,date:fd.get('date')||today,note:String(fd.get('note')||'').trim()});save();toast('جلسه مطالعه ثبت شد');render()}if(f.id==='internForm'){const title=String(fd.get('title')||'').trim();if(!title){toast('عنوان فعالیت را وارد کن');return}state.internship.push({id:uid(),title,date:fd.get('date')||today,minutes:Number(fd.get('minutes')||0),note:String(fd.get('note')||'').trim(),status:fd.get('status')});save();toast('فعالیت ثبت شد');render()}if(f.id==='profileForm'){state.profile.name=String(fd.get('name')||'').trim();save();toast('پروفایل ذخیره شد');render()}})}
if('serviceWorker' in navigator && location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
// Compatibility: older saved data can include a cloud config; it is ignored and never used.
bindEvents();render();if(state.settings.notifications)setupAlarms();
function refreshToday(){const n=iso(new Date());if(n===today)return;const was=selectedDate===today;today=n;if(was)selectedDate=n;if(state.settings.notifications)setupAlarms();render()}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshToday()});setInterval(refreshToday,60000);
window.RoozYarApp?.addListener?.('backButton',()=>{const m=$('#modal');if(m?.open){m.close();return}if(page==='module'){page='modules';render();return}if(page!=='home'){setPage('home');return}window.RoozYarApp.exitApp?.()});
